"""Writes src/dashboard/pyattach/nfc_table.rs: the canonical decompositions NFC needs (#12029 P2h).

Why: `dashboard_attach.clean_name` runs `unicodedata.normalize("NFC", name)` and the crate takes no Unicode
normalization dependency, so the port carries the tables of the Python that froze the script.
What: every code point with a canonical decomposition (Hangul syllables are algorithmic and left out), as
(code point | COMPOSES, first, second or 0), sorted; COMPOSES (bit 31) marks a primary composite, found as
NFC(first + second) == code point. The combining classes are written as (start, end, class) ranges.
Usage: python3 regen_nfc.py > src/dashboard/pyattach/nfc_table.rs
"""
import sys
import unicodedata as u

dec, ccc = [], []
for cp in range(0x110000):
    c = chr(cp)
    d = u.decomposition(c)
    if d and not d.startswith("<") and not 0xAC00 <= cp <= 0xD7A3:
        parts = [int(x, 16) for x in d.split()]
        a, b = parts[0], (parts[1] if len(parts) > 1 else 0)
        comp = b and u.normalize("NFC", chr(a) + chr(b)) == c
        dec.append(((1 << 31 if comp else 0) | cp, a, b))
    k = u.combining(c)
    if k:
        if ccc and ccc[-1][1] == cp - 1 and ccc[-1][2] == k:
            ccc[-1][1] = cp
        else:
            ccc.append([cp, cp, k])


def rows(items, per, fmt):
    for i in range(0, len(items), per):
        yield "    " + " ".join(fmt(x) for x in items[i:i + per])


out = sys.stdout
out.write("//! Canonical decompositions and combining classes for NFC, as Python reports them (#12029 P2h).\n//!\n")
out.write(f"//! Generated by `tests/fixtures/replay/dashboard_attach/regen_nfc.py` from Python\n")
out.write(f"//! {sys.version.split()[0]}, Unicode {u.unidata_version}. Do not edit by hand.\n\n")
out.write("/// Bit 31 of a [`DECOMP`] code point: the pair composes back to it.\npub(crate) const COMPOSES: u32 = 1 << 31;\n\n")
out.write(f"/// `(code point | COMPOSES, first, second or 0)`, sorted by code point.\n#[rustfmt::skip]\npub(crate) static DECOMP: [(u32, u32, u32); {len(dec)}] = [\n")
out.write("\n".join(rows(dec, 6, lambda x: f"(0x{x[0]:X},0x{x[1]:X},0x{x[2]:X}),")) + "\n];\n\n")
out.write(f"/// `(start, end, class)`: every code point with a non-zero canonical combining class.\n#[rustfmt::skip]\npub(crate) static CCC: [(u32, u32, u8); {len(ccc)}] = [\n")
out.write("\n".join(rows(ccc, 8, lambda x: f"(0x{x[0]:X},0x{x[1]:X},{x[2]}),")) + "\n];\n")
